import './intl'

const [{ transport }, { createSession }, { documentStorage }] = await Promise.all([
	import('./embedded-transport'),
	import('./session'),
	import('./storage'),
])
// This module is generated by the native package store for one immutable active selection.
// @ts-expect-error Installed selection exists only in the release artifact.
const { plugins } = await import('launcher:selection')

const session = createSession(
	transport,
	{
		configStorage: documentStorage(transport, 'config'),
		stateStorage: documentStorage(transport, 'state'),
	},
	plugins,
)
export const dispatch = session.dispatch
export const close = session.close
